func main() {
    db := mustOpenDB()        // ~2 s: connect + migrate
    srv := newServer(db)

    ch := make(chan os.Signal) // unbuffered
    signal.Notify(ch, syscall.SIGTERM, syscall.SIGHUP)

    go func() {
        for s := range ch {
            if s == syscall.SIGHUP {
                srv.reload()
            } else { // SIGTERM
                srv.shutdown()
            }
        }
    }()

    srv.run() // blocks forever
}
